export const SPEAKER_ACTOR={'女税户':'victim1','塞琳':'seline','赫斯特':'hester','布伦':'bren','诺恩':'hero','艾莉娅':'saint','薇蕾娜':'sister','奥伦':'steward','鲁恩':'clerk','阿林':'courier','米拉':'herbalist','蕾娜':'woman','修钟人的妹妹':'oldwoman','托马':'watch','卡德兰':'prelate','追缉官':'captain','罗德':'captain','朵莉':'dolly','巡卫':'guard1'};
export const faceToward=(a,b)=>{if(a&&b&&Math.hypot(a.x-b.x,a.y-b.y)>2)a.angle=Math.atan2(b.y-a.y,b.x-a.x);};
export function faceStory(cine,speaker,previousSpeaker=null){if(!cine||cine.busy())return;const id=cine.stage.speaker_actor_per_line?.[cine.line]||(cine.id==='ch2PursuitStops'&&[1,3].includes(cine.line)?'guard2':SPEAKER_ACTOR[speaker]),actor=cine.get(id);if(!actor||!actor.visible||actor.fall>.4)return;if(cine.faceTargets?.[id]){cine.faceActors();return;}const directed={ch2Arrival:{4:'roadElder'},assassination:{0:'prelate',1:'saint',3:'hero',5:'hero',7:'prelate',15:'hero',16:'guard1',17:'guard1'},canalStart:{6:'hero',7:'captain',8:'saint'}}[cine.id]?.[cine.line];const visible=cine.actors.filter(a=>a!==actor&&a.visible&&!a.fall&&!/^guard/.test(a.id));if(!visible.length)visible.push(...cine.actors.filter(a=>a!==actor&&a.visible&&!a.fall));const target=directed?cine.get(directed):id==='hero'?(visible.find(a=>a.id===SPEAKER_ACTOR[previousSpeaker])||visible.find(a=>a.id==='saint')||visible[0]):(visible.find(a=>a.id==='hero')||visible.find(a=>a.id===SPEAKER_ACTOR[previousSpeaker])||visible[0]);if(target?.visible){faceToward(actor,target);if(!target.fall)faceToward(target,actor);}}
